    c0 = min(c for r, c in cells)
    c1 = max(c for r, c in cells)

    # Colored points on the left/right preserve a gap in that side's projection
    # at their row; all other rows in the rectangle's height project to the edge.
    left_blocked = {r for r in range(r0, r1 + 1)
                    if any(grid[r][c] not in (0, 2) for c in range(c0))}
    right_blocked = {r for r in range(r0, r1 + 1)
